{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 11,
      "text_ar": "I counted her wings that were near the others, and behold, there were eight of them.",
      "verse": 11
    },
    {
      "chapter": 11,
      "text_ar": "I saw, and behold, on the right side one wing arose and reigned over all the earth.",
      "verse": 12
    },
    {
      "chapter": 11,
      "text_ar": "When it reigned, the end of it came, and it disappeared, so that its place appeared no more. The next wing rose up and reigned, and it ruled a long time.",
      "verse": 13
    },
    {
      "chapter": 11,
      "text_ar": "It happened that when it reigned, its end came also, so that it disappeared, like the first.",
      "verse": 14
    },
    {
      "chapter": 11,
      "text_ar": "Behold, a voice came to it, and said,",
      "verse": 15
    },
    {
      "chapter": 11,
      "text_ar": "Listen, you who have ruled over the earth all this time! I proclaim this to you, before you disappear,",
      "verse": 16
    },
    {
      "chapter": 11,
      "text_ar": "none after you will rule as long as you, not even half as long.",
      "verse": 17
    },
    {
      "chapter": 11,
      "text_ar": "Then the third arose, and ruled as the others before, and it also disappeared.",
      "verse": 18
    },
    {
      "chapter": 11,
      "text_ar": "So it went with all the wings one after another, as every one ruled, and then disappeared.",
      "verse": 19
    },
    {
      "chapter": 11,
      "text_ar": "I saw, and behold, in process of time the wings that followed were set up on the right side, that they might rule also. Some of them ruled, but in a while they disappeared.",
      "verse": 20
    }
  ]
}
